/* Import after the host shadcn stylesheet. Activate on <html>, with .dark. */
:root[data-ui-theme="traveler"] {
  color-scheme: dark;
  --background: #111315;
  --foreground: #f2eee5;
  --card: #1b1e21;
  --card-foreground: #f2eee5;
  --popover: #24282d;
  --popover-foreground: #f2eee5;
  --primary: #e4dccb;
  --primary-foreground: #1a1c1f;
  --secondary: #30363d;
  --secondary-foreground: #f2eee5;
  --muted: #24282d;
  --muted-foreground: #b9b3a7;
  --accent: #30363d;
  --accent-foreground: #f2eee5;
  --destructive: #e6a19a;
  --destructive-foreground: #261513;
  --border: #666761;
  --input: #96968d;
  --ring: #c2d7e8;
  --radius: 0.125rem;
  --font-sans:
    system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-heading: Georgia, "Times New Roman", serif;
  --trav-rule: #96968d;
  --trav-ornament: #baa680;
  --trav-success: #b9ceac;
  --trav-success-foreground: #182014;
  --trav-panel-shadow: 0 4px 16px #00000030;
  --trav-duration: 140ms;
  --trav-marker-size: 0.3rem;
}

@theme inline {
  --font-heading: var(--font-heading);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-trav-ornament: var(--trav-ornament);
  --color-trav-success: var(--trav-success);
  --color-trav-success-foreground: var(--trav-success-foreground);
  --shadow-trav-panel: var(--trav-panel-shadow);
}

@layer components {
  :where(:root[data-ui-theme="traveler"]) .trav-control {
    outline: 2px solid transparent;
    outline-offset: 3px;
    transition:
      color var(--trav-duration),
      background-color var(--trav-duration),
      border-color var(--trav-duration);
  }

  :where(:root[data-ui-theme="traveler"]) .trav-control:focus-visible {
    outline-color: var(--ring);
  }

  :where(:root[data-ui-theme="traveler"]) .trav-panel {
    box-shadow:
      var(--trav-panel-shadow),
      inset 0 0 0 3px var(--trav-panel-background, var(--card)),
      inset 0 0 0 4px color-mix(in srgb, var(--border) 38%, transparent);
  }
}

@media (prefers-reduced-motion: reduce) {
  :root[data-ui-theme="traveler"] {
    --trav-duration: 0ms;
  }
}

@media (forced-colors: active) {
  @layer components {
    :where(:root[data-ui-theme="traveler"]) .trav-control:focus-visible {
      outline-color: Highlight;
    }

    :where(:root[data-ui-theme="traveler"]) .trav-panel {
      box-shadow: none;
      border-color: CanvasText;
    }
  }
}

@layer components {
  :where(:root[data-ui-theme="traveler"]) .trav-menu-surface {
    --trav-panel-background: var(--popover);
  }

  :where(:root[data-ui-theme="traveler"]) .trav-menu-item {
    outline: 1px solid transparent;
    outline-offset: -2px;
    transition: background-color var(--trav-duration);
  }

  :where(:root[data-ui-theme="traveler"]) .trav-menu-item[data-highlighted] {
    background-color: var(--accent);
    outline: 1px solid var(--ring);
    outline-offset: -2px;
  }

  :where(:root[data-ui-theme="traveler"]) .trav-menu-item[data-disabled] {
    pointer-events: none;
    opacity: 0.6;
  }

  :where(:root[data-ui-theme="traveler"]) .trav-menu-pointer::before {
    position: absolute;
    inset-inline-start: 0.65rem;
    width: var(--trav-marker-size);
    height: var(--trav-marker-size);
    content: "";
    background: currentColor;
    transform: rotate(45deg);
    visibility: hidden;
    pointer-events: none;
  }

  :where(:root[data-ui-theme="traveler"])
    .trav-menu-pointer[data-highlighted]::before {
    visibility: visible;
  }

  :where(:root[data-ui-theme="traveler"]) .trav-overlay[data-state="open"] {
    animation: trav-enter var(--trav-duration) ease-out;
  }

  @keyframes trav-enter {
    from {
      opacity: 0;
    }
    to {
      opacity: 1;
    }
  }
}

@media (forced-colors: active) {
  @layer components {
    :where(:root[data-ui-theme="traveler"]) .trav-menu-item[data-highlighted] {
      outline-color: Highlight;
    }
  }
}
